def angie(*, source: Directory | None = None, node_version: str = '22', self_improve: str = 'off', session: _Session | None = None,) -> Angie:
    """
    AI-powered Angular development agent.

    Uses the Angular CLI MCP server for docs, best practices, build, test,
    and modernize capabilities. Provides workspace tools for reading,
    editing,
    and searching files.

    Pass your Angular project as --source and use the agent entrypoints
    (assist, review, write-tests, build, upgrade) to work with your code,
    or
    install the module and run `dagger agent` to work with Angie
    interactively.

    Parameters
    ----------
    source:
        Angular project source directory
    node_version:
        Node.js version for the Angular CLI MCP server container
    self_improve:
        Self-improvement mode: 'off' (default), 'write' (update context
        file), 'commit' (update + git commit)
    """
    if not (source is None or isinstance(source, Directory)):
        raise _type_error("angie", "source", source, "Directory | None")
    if not (isinstance(node_version, str)):
        raise _type_error("angie", "node_version", node_version, "str")
    if not (isinstance(self_improve, str)):
        raise _type_error("angie", "self_improve", self_improve, "str")
    _args = [
        _Arg("source", source, None),
        _Arg("nodeVersion", node_version, '22'),
        _Arg("selfImprove", self_improve, 'off'),
    ]
    return _client_root(Angie, _TARGET, "angie", _args, session=session)


